V_f = Mamba2_Block(V_img)        // 1D SSM scan through Mamba-2 layer
// 后向扫描：反转patch顺序
V_b = Mamba2_Block(flip(V_img))
// 合并前后向信息
V_scan = V_f + flip(V_b)         // ∈ R^{729×D_v}

// 每个Mamba2_Block内部:
