// Step 2: SwiGLU Feature Extraction
V_gate = Linear_gate(V_scan)     // gate projection
V_proj = Linear_proj(V_scan)     // value projection
V_swiglu = SiLU(V_gate) ⊙ V_proj  // gated activation ∈ R^{729×D_v}

